function sanitizeExpression(expr){ // remove any characters except digits, operators, parentheses, decimal and percent
  return expr.replace(/[^0-9+\-*/().% ]/g,'');}

function evaluateExpression(expr){ try{
    // handle percentage: replace 'number%' with '(number/100)'
    expr = expr.replace(/(\d+(?:\.\d+)?)%/g, '($1/100)');
    expr = sanitizeExpression(expr);
    // avoid accidental leading operators
    if(!expr.trim()) return '0';
    // Use Function to evaluate simple arithmetic
    var result = Function('return ' + expr)();
    if(typeof result === 'number' && !isFinite(result)) return 'Error';
    if(typeof result === 'number'){
      // format with up to 6 decimals, trim trailing zeros
      return Number.isInteger(result)? result.toString() : parseFloat(result.toFixed(6)).toString();
    }
    return result.toString();
  }catch(e){return 'Error';}}

function updateDisplay(text, exprText){
  var display = document.getElementById('display');
  var expr = document.getElementById('expr');
  display.textContent = text;
  expr.textContent = exprText || '\u00A0';
}

function insertValue(val){
  var display = document.getElementById('display');
  var current = display.textContent || '0';
  // if current is '0' or Error, replace
  if(current === '0' || current === 'Error'){
    updateDisplay(val.toString());
  } else {
    updateDisplay(current + val.toString());
  }
}

function handleButtonClick(btn){
  var action = btn.getAttribute('data-action');
  var value = btn.getAttribute('data-value');
  var displayEl = document.getElementById('display');
  var exprEl = document.getElementById('expr');
  var cur = displayEl.textContent || '';

  if(action === 'clear'){
    updateDisplay('0','');
    return;
  }
  if(action === 'back'){
    if(cur.length <= 1){ updateDisplay('0',''); }
    else updateDisplay(cur.slice(0,-1));
    return;
  }
  if(action === 'equals'){
    var result = evaluateExpression(cur);
    updateDisplay(result, cur + ' =');
    return;
  }
  if(value){
    // numeric or operator
    // If current is result from last evaluation (contains '=' in expr), reset
    if(exprEl.textContent && exprEl.textContent.indexOf('=')!==-1){ updateDisplay('0',''); }
    // Insert value
    insertValue(value);
  }
}

