document.addEventListener('DOMContentLoaded', function(){
  // wire metric buttons
  document.querySelectorAll('.metric-btn').forEach(function(btn){
    btn.addEventListener('click', function(){
      var v = btn.getAttribute('data-value');
      // Insert with parentheses if it's a large number to allow arithmetic
      insertValue('('+v+')');
    });
  });

  // wire calculator buttons
  document.querySelectorAll('.btn').forEach(function(btn){
    btn.addEventListener('click', function(){ handleButtonClick(btn); });
  });

  // keyboard support
  document.addEventListener('keydown', function(e){
    var allowed = '0123456789+-*/().%';
    if(allowed.indexOf(e.key) !== -1){ insertValue(e.key); e.preventDefault(); }
    else if(e.key === 'Enter'){ handleButtonClick(document.querySelector('[data-action="equals"]')); e.preventDefault(); }
    else if(e.key === 'Backspace'){ handleButtonClick(document.querySelector('[data-action="back"]')); e.preventDefault(); }
    else if(e.key === 'Escape'){ handleButtonClick(document.querySelector('[data-action="clear"]')); e.preventDefault(); }
  });

  // initialize
  updateDisplay('0','');
});
